import pandas as pd import itertools
def join_unique(series): values = series.dropna().astype(str).str.strip().unique() return ";".join(values)
output = pd.read_csv("$input_file", sep="\t") col_name = output.columns[$column_name - 1]
for effect, effect_group in output.groupby(by="effect", as_index=False): file_name = effect.strip().lower().replace(" ", "_") final_output = effect_group.copy()[[col_name]].drop_duplicates() final_output.set_index(col_name, inplace=True)
basenames = list([col for col in effect_group.columns if col not in [col_name, "effect", "relationship"]]) colnames = [col for col in itertools.product(effect_group["relationship"].unique(), ["hits"] + basenames)] colnames = [f"{col[1]}({col[0]})" for col in colnames]
final_output[colnames] = pd.NA
for col_value, subset in effect_group.groupby(by=col_name, as_index=False): for relationship, relationship_group in subset.groupby(by="relationship"): result = relationship_group.agg(join_unique).drop(["relationship", "effect"]).add_suffix(f"({relationship})").rename({f"{col_name}({relationship})": col_name}).to_frame().T result[f"hits({relationship})"] = len(relationship_group) result.set_index(col_name, inplace=True) final_output.update(result)
if $as_excel: final_output.to_excel(f"./{file_name}.xlsx") else: final_output.to_csv(f"./{file_name}.tsv", sep="\t")
